#!/bin/sh
#
# Generated by the sh backend. Non-POSIX constructs used:
# - 'local': variable scoping (POSIX sh lacks local, but dash/bash/zsh support it)
# - Array emulation (name_0, name_len): arrays are not POSIX
# - '(( ))' arithmetic: required for integer comparison in conditions
# - 'grep -P' helper: PCRE not in POSIX, checked at runtime
#
_num() {
    # bash coerces non-numeric arith values to 0; dash errors
    case "$1" in
        ''|'-'|*[!0-9-]*|-*[!0-9]*) echo 0 ;;
        *) echo "$1" ;;
    esac
}

( { __sh2_tc0="$(printf '%s\n' "$var" | tr '[:upper:]' '[:lower:]')"; if printf '%s\n' ""${__sh2_tc0}"" | grep -Eq '^[a-z]+$'; then { i=$((i == 0)); while [ "$(($( _num "$i" )<${#$( _num "$array" )[@]}))" -ne 0 ]; do if [ "$(($( _num "$array" )[$( _num "$i" )] > $( _num "$threshold" )))" -ne 0 ] && [ -f "${files[i]}" ]; then result_i=$(false); result_len=$(( ${result_len:-0} + 1 )); result_keys="${result_keys:-} i"; fi; : $((((i = i + 1) - 1))); done; }; fi; } ) | sort -n | tail -n 5 >final_result.txt
